#include <pe-parse/parse.h>
#include "fixture.hpp"
#include <iostream>
int main(){for(bool wide:{false,true}){auto b=basic_debug_pe(wide,false);auto p=peparse::ParsePEFromPointer(b.data(),b.size());if(!p){std::cerr<<peparse::GetPEErrString()<<"\n";return 1;}unsigned count=0;peparse::IterDebugs(p,[](void*c,const std::uint32_t&type,const peparse::bounded_buffer*data){if(type!=2||data->bufLen!=33||std::memcmp(data->buf,"RSDS",4))return 1;++*static_cast<unsigned*>(c);return 0;},&count);if(count!=1)return 2;peparse::DestructParsedPE(p);std::cout<<(wide?"PE32+":"PE32")<<" mapped_codeview=1 payload=RSDS\n";auto overlay=basic_debug_pe(wide,true);auto op=peparse::ParsePEFromPointer(overlay.data(),overlay.size());std::cout<<(wide?"PE32+":"PE32")<<" overlay_parse="<<(op?"accepted":"rejected")<<"\n";if(op){peparse::DestructParsedPE(op);return 3;}else{std::cout<<"parse_error="<<peparse::GetPEErr()<<" message="<<peparse::GetPEErrString()<<" location="<<peparse::GetPEErrLoc()<<"\n";}}std::cout<<"PE_DEBUG_CURRENT_BEHAVIOR_OK\n";}
